using System;
using System.IO;
using System.Reflection;
namespace PZ3D {
 static class PresentationBridgeTests {
  static void LegacyMigration(){string root=Path.Combine(Path.GetTempPath(),"orange-legacy-migration-"+Guid.NewGuid().ToString("N"));var e=new Engine(Path.Combine(root,"game"),Path.Combine(root,"user"),Path.Combine(root,"data"),true);Directory.CreateDirectory(e.Game);Directory.CreateDirectory(e.Data);Directory.CreateDirectory(Path.GetDirectoryName(e.Mods));File.WriteAllText(e.Mods,"mods\n{\nmod = Other,\n}\n");File.WriteAllText(e.Config,"{\"vmArgs\":[\"-agentlib:zbNative\",\"-Xmx12345m\",\"-javaagent:OrangeShootPresentation.jar\"]}");File.WriteAllText(Path.Combine(e.Game,PresentationBridge.Name),"legacy fixture");File.WriteAllText(Path.Combine(e.Game,PresentationBridge.ConfigName),"legacy config");var bridge=new PresentationBridge();string journal=(string)typeof(PresentationBridge).GetMethod("Journal",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(bridge,new object[]{e});File.WriteAllText(journal,"{\"jarHash\":\"fixture\",\"propertiesHash\":\"fixture\",\"backup\":\"fixture\"}");string result=bridge.RepairStartup(e);Check(!File.ReadAllText(e.Config).Contains("-javaagent:OrangeShootPresentation.jar")&&File.ReadAllText(e.Config).Contains("-Xmx12345m")&&File.ReadAllText(e.Config).Contains("-agentlib:zbNative")&&File.ReadAllText(e.Mods).Contains("mod = Other,"),"repair removes only old extra agent and preserves memory Buddy and mods");Check(!File.Exists(Path.Combine(e.Game,PresentationBridge.Name))&&result.Contains("备份"),"old managed plugin retained in recovery backup instead of total reinstall");}
  static void Check(bool v,string s){if(!v)throw new Exception("FAIL: "+s);Console.WriteLine("PASS: "+s);}
  public static void Run(){string root=Path.Combine(Path.GetTempPath(),"orange-buddy-addon-"+Guid.NewGuid().ToString("N"));var e=new Engine(Path.Combine(root,"game"),Path.Combine(root,"user"),Path.Combine(root,"data"),true);Directory.CreateDirectory(e.Game);Directory.CreateDirectory(Path.GetDirectoryName(e.Mods));File.WriteAllText(e.Config,"{\"vmArgs\":[\"-agentlib:zbNative\",\"-Xmx12345m\",\"-Dother=true\"]}");string mods="mods\n{\nmod = ZombieBuddy,\nmod = Viewpoint,\nmod = ShootToThrillMultiplayer,\nmod = Other,\n}\n";File.WriteAllText(e.Mods,mods);File.WriteAllText(Path.Combine(e.Game,"ZombieBuddy.jar"),"fixture");File.WriteAllText(Path.Combine(e.Game,"zbNative.dll"),"fixture");string source=Path.Combine(root,"source"),folder=Path.Combine(source,"mods",ShootClient.Id);Directory.CreateDirectory(Path.Combine(folder,"common"));Directory.CreateDirectory(Path.Combine(folder,"42","media","java","client"));File.WriteAllText(Path.Combine(folder,"common","mod.info"),"id="+ShootClient.Id+"\n");File.WriteAllText(Path.Combine(folder,"42","media","java","client","ISeeThem.jar"),"different publisher version fixture");var bridge=new PresentationBridge();string original=File.ReadAllText(e.Config);File.WriteAllText(Path.Combine(e.Game,PresentationBridge.Name),"unmanaged");bool rejected=false;try{bridge.Enable(e,source);}catch{rejected=true;}Check(rejected&&File.ReadAllText(e.Mods)==mods,"unknown legacy files are not overwritten");File.Delete(Path.Combine(e.Game,PresentationBridge.Name));string journal=(string)typeof(PresentationBridge).GetMethod("Journal",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(bridge,new object[]{e});Directory.CreateDirectory(journal);rejected=false;try{bridge.Enable(e,source);}catch{rejected=true;}Check(rejected&&File.ReadAllText(e.Mods)==mods&&File.ReadAllText(e.Config)==original&&!File.Exists(PresentationBridge.PropertiesPath(e)),"journal failure rolls back addon files and mod selection");Directory.Delete(journal);bridge.Enable(e,source);Check(bridge.Enabled(e)&&File.ReadAllText(e.Config)==original&&File.ReadAllText(e.Mods).Contains("mod = OrangeShootPresentation,")&&File.ReadAllText(e.Mods).Contains("mod = Other,"),"Buddy addon install preserves launcher and other mods without javaagent");string properties=PresentationBridge.PropertiesPath(e),before=File.ReadAllText(properties);Check(before.Contains("shoot.sha256="),"current deployment identity is recorded rather than fixed whitelist");using(var locked=new FileStream(journal,FileMode.Open,FileAccess.Read,FileShare.Read)){rejected=false;try{bridge.Disable(e);}catch{rejected=true;}Check(rejected&&bridge.Enabled(e),"locked journal prevents addon uninstall before mutation");}File.AppendAllText(properties,"manual-edit=true\n");bridge.Disable(e);Check(!bridge.Enabled(e)&&!File.ReadAllText(e.Mods).Contains("mod = OrangeShootPresentation,")&&File.ReadAllText(e.Mods).Contains(ShootClient.Id)&&File.ReadAllText(e.Mods).Contains("mod = Other,")&&File.ReadAllText(e.Config)==original,"uninstall removes only own addon and preserves shooting base launcher");Check(Directory.GetFiles(bridge.LastBackup).Length>=4,"uninstall retains edited addon and configuration backup");}
 }
}
